translated = []
unhandled = []

for item in lar_items:
    k = item['key']
    v = item['val']
    if k in translations:
        nv = translations[k]
    else:
        unhandled.append((k, v))
        nv = v
    translated.append({
        'key': k,
        'ver': item['ver'],
        'val': nv,
        'comm': item['comm']
    })

print(f"Total lar items: {len(lar_items)}")
print(f"Unhandled count: {len(unhandled)}")
for u in unhandled[:10]:
    print("  ", u)

with open('scripts/lar_operations_translated.json', 'w', encoding='utf-8') as f:
    json.dump(translated, f, ensure_ascii=False, indent=2)
